fn main() -> i64 with IO, Mut, Div, Panic {
    println("==============================================================")
    println("  Epistemic ODE Solver Validation Suite")
    println("==============================================================")
    var n_pass = 0

    // ---- Part A: Deterministic 14-comp PBPK (no GUM) ----
    println("")
    println("  Part A: Deterministic 14-comp PBPK (dt=0.002h, 12000 steps, 24h)")

    let sys14 = ODESystem { system_id: 2, n_dims: 14 }
    var params = pbpk_14_default_params()
    var state14 = estate_new(14)
    estate_set(&!state14, 13, 2.0, 0.0)  // 2 mg oral, no variance

    var t = 0.0
    let dt14 = 0.002
    var step = 0
    while t < 24.0 && step < 12001 {
        let h = ode_min(dt14, 24.0 - t)
        if h <= 1.0e-15 { t = 24.0 }
        else {
            rk4_step_det(&sys14, t, &!state14, &params, h)
            t = t + h
            step = step + 1
        }
    }

    // T1: Completed
    let t1 = step > 100
    if t1 { println("  PASS T1: 14-comp RK4 completed") } else { println("  FAIL T1") }
    if t1 { n_pass = n_pass + 1 }

    // T2: Plasma concentration is reasonable (not blown up)
    let c_plasma = state14.values[0]
    println("  C_plasma at 24h: "); println(c_plasma)
    let t2 = c_plasma >= 0.0 && c_plasma < 10.0
    if t2 { println("  PASS T2: Plasma concentration reasonable") } else { println("  FAIL T2: C_plasma out of range") }
    if t2 { n_pass = n_pass + 1 }

    // T3: All tissues non-negative
    var all_nn = true
    var d = 0
    while d < 14 {
        if state14.values[d] < -1.0e-6 { all_nn = false }
        d = d + 1
    }
    if all_nn { println("  PASS T3: All tissues non-negative") } else { println("  FAIL T3") }
    if all_nn { n_pass = n_pass + 1 }

    // T4: Gut lumen absorbed
    let lumen = ode_abs(state14.values[13])
    println("  Gut lumen remaining: "); println(lumen)
    let t4 = lumen < 0.001
    if t4 { println("  PASS T4: Oral absorption complete") } else { println("  FAIL T4") }
    if t4 { n_pass = n_pass + 1 }

    // T5: Fat compartment has drug (lipophilic, high Kp_fat=12)
    let c_fat = state14.values[9]
    println("  C_fat at 24h: "); println(c_fat)
    let t5 = c_fat > 0.0
    if t5 { println("  PASS T5: Fat tissue has rapamycin (lipophilic)") } else { println("  FAIL T5") }
    if t5 { n_pass = n_pass + 1 }

    // ---- Part B: GUM on Exponential Decay (1-comp) ----
    println("")
    println("  Part B: GUM Variance on Exponential Decay (1-comp)")

    let sys1 = ODESystem { system_id: 1, n_dims: 1 }
    var p1 = ode_params_new()
    ode_params_set(&!p1, 0, 0.5, 0.01)  // k=0.5 h⁻¹, var(k)=0.01
    var s1 = estate_new(1)
    estate_set(&!s1, 0, 100.0, 4.0)  // y0=100, var(y0)=4

    t = 0.0
    let dt1 = 0.1
    step = 0
    while t < 5.0 && step < 100 {
        rk4_step_gum_1d(&sys1, t, &!s1, &p1, dt1)
        t = t + dt1
        step = step + 1
    }

    // Analytical: y(5) = 100 * exp(-0.5*5) = 100 * exp(-2.5) ≈ 8.208
    let y_final = s1.values[0]
    let v_final = s1.variances[0]
    println("  y(5h): "); println(y_final)
    println("  Var(y) at 5h: "); println(v_final)

    // T6: Value close to analytical (within 5%)
    let y_exact = 8.208  // exp(-2.5)*100
    let rel_err = ode_abs(y_final - y_exact) / y_exact
    println("  Relative error vs analytical: "); println(rel_err)
    let t6 = rel_err < 0.05
    if t6 { println("  PASS T6: RK4 matches analytical exp decay") } else { println("  FAIL T6") }
    if t6 { n_pass = n_pass + 1 }

    // T7: Variance is positive (value decays, so absolute variance may decrease,
    //     but it should remain > 0 from parameter uncertainty contribution)
    let t7 = v_final > 0.0
    if t7 { println("  PASS T7: GUM variance propagated through ODE") } else { println("  FAIL T7: Variance did not propagate") }
    if t7 { n_pass = n_pass + 1 }

    // T8: Variance is reasonable (not blown up to infinity)
    let t8 = v_final < 1.0e10
    if t8 { println("  PASS T8: Variance bounded (no blow-up)") } else { println("  FAIL T8") }
    if t8 { n_pass = n_pass + 1 }

    println("")
    println("==============================================================")
    println("  RESULT: "); println(n_pass); println(" / 8 PASS")
    println("==============================================================")
    if n_pass == 8 { 0 } else { 1 }
}

//@ run-pass
//@ requires: madaros
//@ expect-stdout: VAR_ACCUM_OK

// Regression pin for #1535: a mutable local must carry its uncertainty across
// reassignment, including when it was initialised from an EXPRESSION and when the
// reassignment happens inside a loop.
//
// Two defects sat here, and the second hid behind the first:
//
//   1. Assignment REBOUND the local's variance/sens to the RHS's fresh vregs
//      instead of copying into fixed slots. A rebind is a compile-time map update
//      and a loop body's IR is emitted once, so every iteration recomputed from
//      the pre-loop uncertainty and only one iteration's contribution survived.
//
//   2. The fix for (1) allocated those slots BEFORE the branches that bind a
//      declaration's variance from its RHS, so those branches overwrote them.
//      Only a literal-initialised local escaped, because a literal leaves those
//      branches nothing to bind.
//
// Truth values below are first-order GUM propagation, computed independently
// rather than read off either engine. var(cl) = 1.24^2 = 1.5376.
//
// TEST 1 deliberately uses NO loop. The defect never needed one — a loop only
// turned a wrong answer into a catastrophic one. Four loop-based repros failed to
// separate the two causes; three straight-line assignments did it immediately.
// If this pin ever regresses, TEST 1 is the one that localises it.

fn approx(actual: f64, expected: f64, tol: f64) -> bool {
    let d = actual - expected
    if d < 0.0 { return (0.0 - d) < tol }
    return d < tol
}

fn main() with IO, Mut, Div, Epistemic {
    let k: Knowledge<f64> = measure(12.4, uncertainty: 1.24)
    let cl = k.value
    let v0 = 5.0

    // TEST 1 — expression-initialised accumulator, no loop.
    // Each `+ 0.1*cl` adds 0.1 to d(a)/d(cl), so after n assignments
    // var = (0.1n)^2 * 1.5376.
    var a = 6.0 / v0
    a = a + 0.1 * cl
    let a1 = variance_of(a)          // (0.1)^2 * 1.5376 = 0.015376
    a = a + 0.1 * cl
    let a2 = variance_of(a)          // (0.2)^2 * 1.5376 = 0.061504
    a = a + 0.1 * cl
    let a3 = variance_of(a)          // (0.3)^2 * 1.5376 = 0.138384

    let t1 = approx(a1, 0.015376, 0.000001)
        && approx(a2, 0.061504, 0.000001)
        && approx(a3, 0.138384, 0.000001)

    // TEST 2 — same accumulation in a loop: 20 steps, d(b)/d(cl) = 2.0,
    // var = 4 * 1.5376 = 6.1504. Before the fix this read 0.015376 (one step).
    var b = 6.0 / v0
    var i: i64 = 0
    while i < 20 {
        b = b + 0.1 * cl
        i = i + 1
    }
    let t2 = approx(variance_of(b), 6.150400, 0.000001)

    // TEST 3 — self-dependent accumulation in a loop.
    // c = (1+u)^2 with u = measure(2.0, 0.5): d(c)/d(u) = 2(1+u) = 6, var = 36*0.25 = 9.
    let ku: Knowledge<f64> = measure(2.0, uncertainty: 0.5)
    let u = ku.value
    var c = 1.0
    var j: i64 = 0
    while j < 2 {
        c = c + u * c
        j = j + 1
    }
    let t3 = approx(variance_of(c), 9.000000, 0.000001)

    // TEST 4 — straight-line correlation must be unaffected by all of the above.
    let z = cl - cl
    let s = cl + cl + cl
    let t4 = approx(variance_of(z), 0.0, 0.000001)
        && approx(variance_of(s), 13.838400, 0.000001)

    if t1 && t2 && t3 && t4 {
        println("VAR_ACCUM_OK")
        return
    }

    print("VAR_ACCUM_FAIL t1_expr_init_noloop=")
    print_f64(a1)
    print(",")
    print_f64(a2)
    print(",")
    print_f64(a3)
    print(" t2_loop=")
    print_f64(variance_of(b))
    print(" t3_selfdep=")
    print_f64(variance_of(c))
    print(" t4_straightline=")
    print_f64(variance_of(s))
    println("")
}

//@ run-pass
//@ requires: lean_single
//@ description: #2387 — lean_single binary128 survives calls, returns, IEEE compares and f64 casts
//@ expect-stdout-contains: PASS f128_lean_single_binary128_calls
//
// Params take two ABI slots (lo, hi), returns come back in rax:rdx, compares go
// through libgcc __eqtf2/__lttf2/... (IEEE: NaN unordered, -0 == +0), and an
// exactly-representable f64 literal widens to f128 in argument, return and
// comparison position. 1 + 2^-100 != 1 only holds in binary128.

fn add128(a: f128, b: f128) -> f128 {
    a + b
}

fn sub_ret(a: f128, b: f128) -> f128 {
    return a - b
}

fn half() -> f128 {
    0.5
}

fn mix(n: i64, a: f128, m: i64, b: f128) -> f128 {
    if n + m != 7 { return 0.0 }
    a * b
}

fn sum4(a: f128, b: f128, c: f128, d: f128) -> f128 {
    a + b + c + d
}

fn main() -> i32 with IO, Mut, Panic, Div {
    let one: f128 = 1.0
    let two: f128 = 2.0
    let three: f128 = 3.0
    if add128(one, two) != three { println("FAIL var args"); return 1 }
    if add128(1.0, 2.0) != three { println("FAIL literal args"); return 2 }
    if sub_ret(three, 1.0) != two { println("FAIL explicit return"); return 3 }
    if half() + half() != one { println("FAIL tail widen"); return 4 }
    if mix(3, three, 4, two) != 6.0 { println("FAIL mixed params"); return 5 }
    if sum4(one, one, one, one) != 4.0 { println("FAIL stack params"); return 6 }

    if (one < two) == false { println("FAIL <"); return 10 }
    if (two > one) == false { println("FAIL >"); return 11 }
    if (one <= one) == false { println("FAIL <="); return 12 }
    if one >= two { println("FAIL >="); return 13 }
    let zero: f128 = 0.0
    let neg_zero = -zero
    if neg_zero != zero { println("FAIL -0 == +0"); return 14 }
    let nan = zero / zero
    if nan == nan { println("FAIL nan == nan"); return 15 }
    if (nan != nan) == false { println("FAIL nan != nan"); return 16 }
    if nan < one || nan > one || nan <= one || nan >= one { println("FAIL nan ordered"); return 17 }

    var e: f128 = 1.0
    var i = 0
    while i < 100 { e = e / 2.0; i = i + 1 }
    if add128(one, e) == one { println("FAIL binary128 across call"); return 20 }

    let x: f128 = 1.5
    if (x as f64) != 1.5 { println("FAIL f128 as f64"); return 30 }
    if (2.25 as f128) <= x { println("FAIL f64 as f128"); return 31 }

    println("PASS f128_lean_single_binary128_calls")
    return 0
}

