// Main test runner
// =============================================================================

fn main() -> i64 with IO, Mut, Div, Panic {
    println("=== Gaussian Process Regression Tests ===")
    println("")

    // Generate 20 training points: x in [0, 6], y = sin(x) + noise
    var data = GPData {
        x: [0.0; 64],
        y: [0.0; 64],
        n: 20
    }

    var seed: i64 = 42
    var i: i64 = 0
    while i < 20 {
        let xi = (i as f64) * 6.0 / 19.0
        data.x[i as usize] = xi
        GPD.x[i as usize] = xi
        seed = lcg_next(seed)
        let noise = lcg_to_f64(seed) * 0.1
        let yi = gp_sin(xi) + noise
        data.y[i as usize] = yi
        GPD.y[i as usize] = yi
        i = i + 1
    }
    GPD.n = 20

    let params = GPHyperparams {
        length_scale: 1.0,
        signal_var: 1.0,
        noise_var: 0.01,
        kernel_type: 0
    }

    GP_LS = params.length_scale
    GP_SIG = params.signal_var
    GP_NOISE = params.noise_var

    gp_fit_into(&!GPM, params)

    var passed: i64 = 0
    var failed: i64 = 0

    print("T1: GP fit succeeds (Cholesky valid).... ")
    if test_gp_fit() {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
    }

    print("T2: Interpolation at training points.... ")
    if test_interpolation() {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
    }

    // gp_posterior_var_at clobbers GPM.L[1,1] under IEEE-correct compares; snapshot LML first.
    GP_LAST_LML = gp_log_marginal_likelihood()
    print("T3: Variance small near, large far...... ")
    if test_variance_behavior() {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
    }

    print("T4: Log marginal likelihood matches.... ")
    if test_lml() {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
    }

    println("")
    if failed == 0 {
        println("ALL 4 TESTS PASSED")
        return 0
    }
    println("SOME TESTS FAILED")
    return 1
}

