    var sum_sq = 0.0
    var i = 0
    while i < n {
        var j = 0
        while j < n {
            var sum = 0.0
            var k = 0
            while k < n {
                sum = sum + mat_get(ldl.L, n, i, k) * ldl.D[k] * mat_get(ldl.L, n, j, k)
                k = k + 1
            }
            let diff = mat_get(A, n, i, j) - sum
            sum_sq = sum_sq + diff * diff
            j = j + 1
        }
        i = i + 1
    }
    let err = sqrt_f64(sum_sq)
    return err < 1e-10
}

// Test 14: LDL solve matches LU solve
fn test_ldl_solve() -> bool with Mut, Panic, Div {
    let A = make_3x3(
        4.0, 2.0, 0.0,
        2.0, 5.0, 1.0,
        0.0, 1.0, 3.0
    )
    let n = 3
    var b = zeros8()
    b[0] = 1.0
    b[1] = 2.0
    b[2] = 3.0

    let ldl = ldl_factorize(A, n)

    var z = zeros8()
    var i = 0
    while i < n {
        var sum = 0.0
        var j = 0
        while j < i {
            sum = sum + mat_get(ldl.L, n, i, j) * z[j]
            j = j + 1
        }
        z[i] = b[i] - sum
        i = i + 1
    }

    var y = zeros8()
    i = 0
    while i < n {
        y[i] = z[i] / ldl.D[i]
        i = i + 1
    }

    var x_ldl = zeros8()
    i = n - 1
    while i >= 0 {
        var sum = 0.0
        var j = i + 1
        while j < n {
            sum = sum + mat_get(ldl.L, n, j, i) * x_ldl[j]
            j = j + 1
        }
        x_ldl[i] = y[i] - sum
        i = i - 1
    }

    let lu = lu_factorize(A, n)

    var pb = zeros8()
    i = 0
    while i < n {
        pb[i] = b[lu.perm[i]]
        i = i + 1
    }

    var ylu = zeros8()
    i = 0
    while i < n {
        var sum = 0.0
        var j = 0
        while j < i {
            sum = sum + mat_get(lu.L, n, i, j) * ylu[j]
            j = j + 1
        }
        ylu[i] = pb[i] - sum
        i = i + 1
    }

    var x_lu = zeros8()
    i = n - 1
    while i >= 0 {
        var sum = 0.0
        var j = i + 1
        while j < n {
            sum = sum + mat_get(lu.U, n, i, j) * x_lu[j]
            j = j + 1
        }
        x_lu[i] = (ylu[i] - sum) / mat_get(lu.U, n, i, i)
        i = i - 1
    }

    var err = 0.0
    i = 0
    while i < n {
        let diff = x_ldl[i] - x_lu[i]
        err = err + diff * diff
        i = i + 1
    }
    err = sqrt_f64(err)

    return err < 1e-10
}

