    // y = k0 * k1 + k2 * k3
    let y = k0.value * k1.value + k2.value * k3.value

    // ∂y/∂k0 = k1 = 3.0
    let s0 = sensitivity_of(y, 0)
    // ∂y/∂k1 = k0 = 2.0
    let s1 = sensitivity_of(y, 1)
    // ∂y/∂k2 = k3 = 7.0
    let s2 = sensitivity_of(y, 2)
    // ∂y/∂k3 = k2 = 5.0
    let s3 = sensitivity_of(y, 3)

    assert(s0 > 2.99 && s0 < 3.01)
    assert(s1 > 1.99 && s1 < 2.01)
    assert(s2 > 6.99 && s2 < 7.01)
    assert(s3 > 4.99 && s3 < 5.01)
    0
}

//@ requires: madaros
// Seq<f64> element reads are classified as float by the modular Madaros
// codegen (self-hosted/ir/lower.sio, d80435a49e); the lean_single bootstrap
// that builds the suite's stage2 binary has no such classification and reads
// the element as an integer. Measured 2026-09-05, same worktree, engine
// swapped: lean_single rc=1; Madaros built from this branch rc=0. The
// committed bin/madaros-linux-x86_64 (2026-09-03) also rc=1 -- it predates
// the fix, so this needs a refreshed prebuilt before a Madaros job can run it.
//@ run-pass
//@ expect-stdout-contains: SEQ_F64_SCALAR_KIND_OK
// Reading a Seq<f64> element must produce a float, in every spelling.
//
// Seq access is an intrinsic: `seq.get(i)` lowers to __sounio_seq_get with no
// fn symbol, so the two routines that classify an expression's type both missed
// on the mangled-method lookup and fell through to their integer default:
// expr_result_scalar_kind_ref (println) and expr_result_is_float_ref
// (arithmetic). The `a[i]` spelling had an answer in both; the method spelling
// had one in neither.
//
// Measured on the committed compiler before the fix -- a wrong-code path, not a
// rejection, so the program type-checked clean and printed nonsense:
//   sum of 0.25 and 0.75 in a loop  -> 9203105838531608576.0
//   w.get(0) + w.get(1) unrolled    -> 9223372036854775808.0  (2^63)
//   println(w.get(0))               -> refused, "unresolved scalar kind"
// Seq<i64> was correct throughout the same shapes, which is what made this a
// float-classification defect rather than a Seq defect.
//
// NOT covered here: a `&Seq<T>` PARAMETER. That path is separate, and it was
// broken -- reading one indirection level off -- until 2026-09-09. It was not a
// pre-existing defect: the reference-receiver fix in PR #2413 made the call
// resolve without teaching lowering to load through the reference. Fixed by
// lower_seq_recv_base_ref; see tests/run-pass/seq_ref_param_delivers_handle.sio
// and docs/compiler/KNOWN_LIMITATIONS.md.

fn main() -> i32 with IO, Mut, Panic, Epistemic {
    var w: Seq<f64> = seq_new()
    w.push(0.25)
    w.push(0.75)

    // Unrolled: both operands are intrinsic reads.
    let unrolled: f64 = w.get(0) + w.get(1)
    if unrolled < 0.999 || unrolled > 1.001 {
        print("seq_f64: FAIL (unrolled)\n")
        return 1
    }

    // Accumulating loop, i64 counter with a cast in the index.
    var sa: f64 = 0.0
    let k: i64 = w.len().unwrap("len")
    var i: i64 = 0
    while i < k {
        sa = sa + w.get(i as usize)
        i = i + 1
    }
    if sa < 0.999 || sa > 1.001 {
        print("seq_f64: FAIL (i64 loop)\n")
        return 1
    }

    // Same loop with a usize counter and no cast.
    var sb: f64 = 0.0
    let ku: usize = k as usize
    var j: usize = 0
    while j < ku {
        sb = sb + w.get(j)
        j = j + 1
    }
    if sb < 0.999 || sb > 1.001 {
        print("seq_f64: FAIL (usize loop)\n")
        return 1
    }

    // Seq<i64> control: correct before and after, so a fix that breaks this
    // broke integer classification rather than repairing the float one.
    var n: Seq<i64> = seq_new()
    n.push(3)
    n.push(4)
    if n.get(0) + n.get(1) != 7 {
        print("seq_f64: FAIL (i64 control)\n")
        return 1
    }

    print("SEQ_F64_SCALAR_KIND_OK\n")
    0
}

//@ run-pass
// Seq<Struct> with repeated pushes — each pushed struct gets its own heap copy
// (seq_push materializes struct/aggregate elements), so loop-pushed elements do
// NOT alias the same buffer. This is the pattern the ontology relies on
// (class.superclasses.push(iri) in a loop, then indexing distinct elements).
struct IRI { id: i64, ns: i64, local: i64 }
fn mk(n: i64) -> IRI { IRI { id: n, ns: n + 1, local: n + 2 } }
struct Bag { items: Seq<IRI>, tag: i64 }

fn main() -> i32 with IO, Mut, Panic, Epistemic {
    // local Seq, loop push of distinct structs (literal + fn-return)
    var v: Seq<IRI> = seq_new()
    var i = 0
    while i < 12 { v.push(IRI { id: i * 10, ns: i, local: 0 }); i = i + 1 }
    var k = 0
    while k < 12 {
        if v.get(k as i64).id != k * 10 { return 10 }
        if v.get(k as i64).ns != k { return 11 }
        k = k + 1
    }

    // field Seq, loop push via fn-returned struct (SRET) — also must not alias
    var b: Bag = Bag { items: seq_new(), tag: 5 }
    var j = 0
    while j < 9 { b.items.push(mk(j * 100)); j = j + 1 }
    var m = 0
    while m < 9 {
        if b.items[m as i64].id != m * 100 { return 20 }
        if b.items[m as i64].local != m * 100 + 2 { return 21 }
        m = m + 1
    }
    if b.tag != 5 { return 22 }

    return 0
}

//@ run-pass
//@ description: Self-contained bounded SMT/Farkas microkernel smoke

fn smt_farkas2_lhs_sum(a1: i64, a2: i64, y1: i64, y2: i64) -> i64 {
    if y1 < 0 { return 0 - 9001 }
    if y2 < 0 { return 0 - 9001 }
    return (y1 * a1) + (y2 * a2)
}

fn smt_farkas2_rhs_sum(b1: i64, b2: i64, y1: i64, y2: i64) -> i64 {
    if y1 < 0 { return 0 - 9001 }
    if y2 < 0 { return 0 - 9001 }
    return (y1 * b1) + (y2 * b2)
}

fn smt_farkas2_unsat_check(
    a1: i64,
    b1: i64,
    a2: i64,
    b2: i64,
    y1: i64,
    y2: i64) -> i64 {
    if y1 < 0 { return 0 }
    if y2 < 0 { return 0 }
    let lhs = smt_farkas2_lhs_sum(a1, a2, y1, y2)
    if lhs != 0 { return 0 }
    let rhs = smt_farkas2_rhs_sum(b1, b2, y1, y2)
    if rhs < 0 { return 1 }
    return 0
}

fn main() -> i64 {
    let tiny_unsat = smt_farkas2_unsat_check(1, 0, 0 - 1, 0 - 1, 1, 1)
    if tiny_unsat != 1 { return 1 }

    let wrong_multiplier = smt_farkas2_unsat_check(1, 0, 0 - 1, 0 - 1, 1, 0)
    if wrong_multiplier != 0 { return 2 }

    let nonnegative_rhs = smt_farkas2_unsat_check(1, 0, 0 - 1, 1, 1, 1)
    if nonnegative_rhs != 0 { return 3 }

    let negative_multiplier = smt_farkas2_unsat_check(1, 0, 0 - 1, 0 - 1, 1, 0 - 1)
    if negative_multiplier != 0 { return 4 }

    let lhs = smt_farkas2_lhs_sum(1, 0 - 1, 1, 1)
    if lhs != 0 { return 5 }

    let rhs = smt_farkas2_rhs_sum(0, 0 - 1, 1, 1)
    if rhs != 0 - 1 { return 6 }

    let artifact_fp: i64 = 583104927
    let audit_fp: i64 = 719460238
    let instance_fp: i64 = 284916705
    let certificate_fp: i64 = 640271893
    let proof_family_mask: i64 = 3
